# Write a python script to resolve addresses to nearest symbols
python3 << 'PYEOF'
import re

# Read symbols
symbols = []
with open('/tmp/monosgen_syms.txt') as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3 and parts[1] in ('T', 't', 'W', 'w'):
            addr = int(parts[0], 16)
            name = parts[2]
            symbols.append((addr, name))

symbols.sort()

def resolve(addr):
    best = None
    for sa, sn in symbols:
        if sa <= addr:
            best = (sa, sn)
        else:
            break
    if best:
        offset = addr - best[0]
        return f"{best[1]}+0x{offset:x}"
    return "??"

# Addresses to resolve
addrs = {
    "Thread 7020 (main/uiTest.MauiTest)": [
        (0x222098, "#01"),
        (0x2241ac, "#02"),
        (0x1abc80, "#03"),
        (0x16de04, "#04"),
    ],
    "Thread 7046 (SGen worker)": [
        (0x2f4b20, "#02"),
        (0x2f4c84, "#03"),
    ],
    "Thread 7048 (Finalizer)": [
        (0x2c1a40, "#02"),
    ],
}

for thread, frames in addrs.items():
    print(f"\n{thread}:")
    for addr, frame_num in frames:
        sym = resolve(addr)
        print(f"  {frame_num} pc {addr:016x}  libmonosgen-2.0.so  ({sym})")
